#!/usr/bin/env python3
"""Generate the simulated blind-test panel.

This is NOT human data. It exists so the blind-test pipeline can be exercised
end to end without a reviewer panel. The rule is fixed, so the file is
byte-stable across runs.

usage: python3 tools/dry-run-panel/panel.py [out.csv]
"""

import pathlib
import sys

PARAGRAPHS = 30
EVALUATORS = 5
HEADER = [
    "# SIMULATED PANEL: generated by a fixed rule, NOT human preferences.",
    "# Used only to exercise the blind-test pipeline end to end.",
    "paragraph,evaluator,choice",
]


def main() -> int:
    target = pathlib.Path(
        sys.argv[1] if len(sys.argv) > 1 else "corpus/blind/dry-run/simulated-preferences.csv"
    )
    lines = list(HEADER)
    for paragraph in range(PARAGRAPHS):
        for evaluator in range(EVALUATORS):
            choice = "A" if (paragraph * 7 + evaluator * 13) % 10 < 6 else "B"
            lines.append(f"{paragraph},{evaluator},{choice}")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {target} ({PARAGRAPHS} paragraphs x {EVALUATORS} evaluators)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
